name: notify (Discord)
runs-on: ubuntu-latest
needs: [secrets_scan, scan_dependencies, docker_scan, sast, iac_checkov, tests, dast, deploy]
if: always()
steps:
  - name: Notification Discord
    env:
      WEBHOOK: ${{ secrets.DISCORD_WEBHOOK_URL }}
      R_SECRETS: ${{ needs.secrets_scan.result }}
      R_DEPS: ${{ needs.scan_dependencies.result }}
      R_IMAGE: ${{ needs.docker_scan.result }}
      R_SAST: ${{ needs.sast.result }}
      R_IAC: ${{ needs.iac_checkov.result }}
      R_TESTS: ${{ needs.tests.result }}
      R_DAST: ${{ needs.dast.result }}
      R_DEPLOY: ${{ needs.deploy.result }}
      ACTOR: ${{ github.actor }}
      REPO: ${{ github.repository }}
      SHA: ${{ github.sha }}
      RUN_URL: ${{ github.server_url }}/${{ github.repository }}/actions/runs/${{ github.run_id }}
    run: |
      if [ -z "$WEBHOOK" ]; then
        echo "DISCORD_WEBHOOK_URL absent : notification ignoree"
        exit 0
      fi
      OK=1
      for r in "$R_SECRETS" "$R_DEPS" "$R_IMAGE" "$R_SAST" "$R_IAC" "$R_TESTS" "$R_DAST"; do
        [ "$r" = success ] || OK=0
      done
      # deploy est ignore (skipped) sur les pull requests
      [ "$R_DEPLOY" = success ] || [ "$R_DEPLOY" = skipped ] || OK=0
      if [ "$OK" = 1 ]; then
        TITLE="Pipeline DevSecOps : SUCCES"; COLOR=3066993
      else
        TITLE="Pipeline DevSecOps : ECHEC"; COLOR=15158332
      fi
      DESC=$(printf 'Depot : %s\nAuteur : %s\nCommit : %s\n\nGitleaks : %s\nTrivy dependances : %s\nTrivy image : %s\nSemgrep : %s\nCheckov : %s\nTests : %s\nZAP : %s\nDeploy : %s\n\n%s' \
        "$REPO" "$ACTOR" "${SHA:0:7}" "$R_SECRETS" "$R_DEPS" "$R_IMAGE" "$R_SAST" "$R_IAC" "$R_TESTS" "$R_DAST" "$R_DEPLOY" "$RUN_URL")
      PAYLOAD=$(jq -n --arg t "$TITLE" --arg d "$DESC" --argjson c "$COLOR" \
        '{embeds:[{title:$t,description:$d,color:$c}]}')
      curl -sf -H "Content-Type: application/json" -d "$PAYLOAD" "$WEBHOOK"

